create or replace function public.verify_checkin(p_qr_code text,p_lat double precision default null,p_lng double precision default null) returns public.check_ins language plpgsql security definer set search_path=public,pg_temp as $$ declare v_uid uuid:=auth.uid(); v_qr public.qr_codes%rowtype; v_loc public.locations%rowtype; v_check public.check_ins%rowtype; v_distance double precision; v_points integer:=20; begin if v_uid is null then raise exception 'Authentication required'; end if; select * into v_qr from public.qr_codes where code=p_qr_code and active=true limit 1; if not found then raise exception 'Invalid or inactive QR code'; end if; select * into v_loc from public.locations where id=v_qr.location_id and is_active=true and verification_status='verified'; if not found then raise exception 'Location is not currently available for check-in'; end if; if p_lat is not null and p_lng is not null and v_loc.geom is not null then v_distance:=extensions.st_distance(v_loc.geom,extensions.st_setsrid(extensions.st_makepoint(p_lng,p_lat),4326)::extensions.geography); if v_distance>30 then raise exception 'You must be within about 100 feet of this location'; end if; end if; if exists(select 1 from public.check_ins where user_id=v_uid and location_id=v_loc.id and checked_in_at>now()-interval '30 minutes') then raise exception 'Already checked in here recently'; end if; insert into public.check_ins(user_id,location_id,qr_code_id,latitude,longitude,distance_meters,verification_method,points_awarded,metadata) values(v_uid,v_loc.id,v_qr.id,p_lat,p_lng,v_distance,'qr',v_points,jsonb_build_object('source','home_qr_check_in','geofence_meters',30)) returning * into v_check; begin perform public.record_progression_action('qr_scan',v_check.id); exception when others then null; end; begin perform public.record_progression_metric_event('qr_scan','check_in',v_check.id,1,v_points,jsonb_build_object('verification_method','qr','location_id',v_loc.id)); exception when others then null; end; return v_check; end $$; revoke all on function public.verify_checkin(text,double precision,double precision) from public; grant execute on function public.verify_checkin(text,double precision,double precision) to authenticated;
